/// <reference types="vitest/config" />
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  base: '/',
  plugins: [react()],
  server: { proxy: { '/api': 'http://localhost:8080' } },
  build: { outDir: 'dist' },
  test: { environment: 'jsdom', globals: true, setupFiles: ['./src/setupTests.ts'] },
});

import { afterEach } from 'vitest';
import { cleanup } from '@testing-library/react';

afterEach(cleanup);

// jsdom no implementa showModal/close de <dialog>.
const proto = HTMLDialogElement.prototype;
if (typeof proto.showModal !== 'function') {
  proto.showModal = function (this: HTMLDialogElement) {
    this.setAttribute('open', '');
  };
  proto.close = function (this: HTMLDialogElement) {
    this.removeAttribute('open');
    this.dispatchEvent(new Event('close'));
  };
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './styles.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

export type Rol = 'estudiante' | 'coordinador';

export interface Usuario {
  id: string;
  rol: Rol;
  nombre: string;
  programa: string;
}

export interface Cita {
  documento: string;
  seccion: string;
}

export interface Respuesta {
  respuesta: string;
  citas: Cita[];
  usoDatosEstudiante: boolean;
  tokens: number;
  costoUsd: number;
}

export interface SeccionReglamento {
  documento: string;
  seccion: string;
  texto: string;
}

export type TipoError = 'permisos' | 'entrada' | 'proveedor' | 'red' | 'generico';

export class ApiError extends Error {
  constructor(
    public tipo: TipoError,
    message: string,
  ) {
    super(message);
  }
}

export function errorDeEstado(status: number): ApiError {
  switch (status) {
    case 400:
      return new ApiError('entrada', 'La pregunta no es válida. Escribe entre 1 y 1.000 caracteres.');
    case 403:
      return new ApiError(
        'permisos',
        'No tienes permiso para consultar esos datos. Solo puedes ver tu propia información o, si eres coordinador, la de tu programa.',
      );
    case 503:
      return new ApiError('proveedor', 'El asistente no está disponible en este momento. Inténtalo de nuevo más tarde.');
    default:
      return new ApiError('generico', `Ocurrió un error inesperado (código ${status}).`);
  }
}

async function pedir<T>(url: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await (init ? fetch(url, init) : fetch(url));
  } catch {
    throw new ApiError('red', 'No se pudo conectar con el servidor. Revisa tu conexión.');
  }
  if (!res.ok) throw errorDeEstado(res.status);
  try {
    return (await res.json()) as T;
  } catch {
    throw new ApiError('generico', 'La respuesta del servidor no es válida.');
  }
}

export function preguntar(pregunta: string, usuario: Usuario): Promise<Respuesta> {
  return pedir<Respuesta>('/api/asistente/preguntar', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ pregunta, usuario: { rol: usuario.rol, id: usuario.id } }),
  });
}

export function obtenerUsuarios(): Promise<Usuario[]> {
  return pedir<Usuario[]>('/api/usuarios/demo');
}

export function urlSeccion(c: Cita): string {
  return `/api/reglamento/${encodeURIComponent(c.documento)}/${encodeURIComponent(c.seccion)}`;
}

export function obtenerSeccion(c: Cita): Promise<SeccionReglamento> {
  return pedir<SeccionReglamento>(urlSeccion(c));
}

export interface Acumulado {
  tokens: number;
  costoUsd: number;
}

export function acumular(items: Array<{ tokens: number; costoUsd: number }>): Acumulado {
  return items.reduce((a, i) => ({ tokens: a.tokens + i.tokens, costoUsd: a.costoUsd + i.costoUsd }), {
    tokens: 0,
    costoUsd: 0,
  });
}

export const formatoCosto = (n: number) =>
  new Intl.NumberFormat('es-CO', { minimumFractionDigits: 6, maximumFractionDigits: 6 }).format(n);

export const formatoTokens = (n: number) => new Intl.NumberFormat('es-CO').format(n);

import { useEffect, useRef, useState } from 'react';
import { obtenerSeccion, type Cita, type SeccionReglamento } from './api';

interface Props {
  cita: Cita;
  onClose: () => void;
}

export default function CitaDialog({ cita, onClose }: Props) {
  const ref = useRef<HTMLDialogElement>(null);
  const [seccion, setSeccion] = useState<SeccionReglamento | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const d = ref.current;
    if (d && !d.open) d.showModal();
  }, []);

  useEffect(() => {
    let activo = true;
    obtenerSeccion(cita)
      .then((s) => activo && setSeccion(s))
      .catch(() => activo && setError('No se pudo cargar el texto de esta sección.'));
    return () => {
      activo = false;
    };
  }, [cita]);

  return (
    <dialog ref={ref} className="cita-dialog" aria-labelledby="cita-titulo" onClose={onClose}>
      <h2 id="cita-titulo">{cita.seccion}</h2>
      <p className="muted">{cita.documento}</p>
      {error ? (
        <p role="alert" className="error">{error}</p>
      ) : seccion ? (
        <pre className="cita-texto">{seccion.texto}</pre>
      ) : (
        <p role="status">Cargando…</p>
      )}
      <button type="button" onClick={() => ref.current?.close()}>
        Cerrar
      </button>
    </dialog>
  );
}

import { useEffect, useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
import {
  acumular,
  formatoCosto,
  formatoTokens,
  obtenerUsuarios,
  preguntar,
  ApiError,
  type Cita,
  type TipoError,
  type Usuario,
} from './api';
import CitaDialog from './CitaDialog';

const MAX = 1000;

type Mensaje =
  | { id: number; tipo: 'pregunta'; texto: string }
  | {
      id: number;
      tipo: 'respuesta';
      texto: string;
      citas: Cita[];
      uso: boolean;
      tokens: number;
      costoUsd: number;
    }
  | { id: number; tipo: 'error'; texto: string; clase: TipoError };

function temaInicial(): 'light' | 'dark' | null {
  try {
    const t = localStorage.getItem('tema');
    return t === 'light' || t === 'dark' ? t : null;
  } catch {
    return null;
  }
}

export default function App() {
  const [usuarios, setUsuarios] = useState<Usuario[]>([]);
  const [errorUsuarios, setErrorUsuarios] = useState<string | null>(null);
  const [usuarioId, setUsuarioId] = useState('');
  const [mensajes, setMensajes] = useState<Mensaje[]>([]);
  const [texto, setTexto] = useState('');
  const [enviando, setEnviando] = useState(false);
  const [citaAbierta, setCitaAbierta] = useState<Cita | null>(null);
  const [tema, setTema] = useState<'light' | 'dark' | null>(temaInicial);
  const siguienteId = useRef(1);
  const disparador = useRef<HTMLElement | null>(null);
  const version = useRef(0);

  useEffect(() => {
    obtenerUsuarios()
      .then((u) => {
        setUsuarios(u);
        if (u.length) setUsuarioId(u[0].id);
      })
      .catch((e: unknown) =>
        setErrorUsuarios(e instanceof ApiError ? e.message : 'No se pudo cargar la lista de usuarios.'),
      );
  }, []);

  useEffect(() => {
    if (tema) document.documentElement.dataset.tema = tema;
    else delete document.documentElement.dataset.tema;
  }, [tema]);

  const usuario = usuarios.find((u) => u.id === usuarioId);
  const total = acumular(mensajes.flatMap((m) => (m.tipo === 'respuesta' ? [m] : [])));
  const vacio = texto.trim().length === 0;

  function alternarTema() {
    const oscuro =
      tema === 'dark' || (tema === null && window.matchMedia?.('(prefers-color-scheme: dark)').matches);
    const nuevo = oscuro ? 'light' : 'dark';
    setTema(nuevo);
    try {
      localStorage.setItem('tema', nuevo);
    } catch {
      /* almacenamiento no disponible */
    }
  }

  function cambiarUsuario(id: string) {
    version.current++;
    setUsuarioId(id);
    setMensajes([]);
    setTexto('');
    setEnviando(false);
  }

  async function enviar(e?: FormEvent) {
    e?.preventDefault();
    if (!usuario || vacio || enviando || texto.length > MAX) return;
    const pregunta = texto.trim();
    const v = version.current;
    setMensajes((m) => [...m, { id: siguienteId.current++, tipo: 'pregunta', texto: pregunta }]);
    setTexto('');
    setEnviando(true);
    let nuevo: Mensaje;
    try {
      const r = await preguntar(pregunta, usuario);
      nuevo = {
        id: siguienteId.current++,
        tipo: 'respuesta',
        texto: r.respuesta,
        citas: r.citas,
        uso: r.usoDatosEstudiante,
        tokens: r.tokens,
        costoUsd: r.costoUsd,
      };
    } catch (err) {
      const a = err instanceof ApiError ? err : new ApiError('generico', 'Ocurrió un error inesperado.');
      nuevo = { id: siguienteId.current++, tipo: 'error', texto: a.message, clase: a.tipo };
    }
    if (v !== version.current) return; // el usuario cambió mientras tanto
    setMensajes((m) => [...m, nuevo]);
    setEnviando(false);
  }

  function onKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      void enviar();
    }
  }

  function abrirCita(c: Cita, el: HTMLElement) {
    disparador.current = el;
    setCitaAbierta(c);
  }

  function cerrarCita() {
    setCitaAbierta(null);
    disparador.current?.focus();
  }

  return (
    <div className="app">
      <header className="cabecera">
        <h1>TutorFlow</h1>
        <button type="button" className="secundario" onClick={alternarTema}>
          Cambiar tema claro/oscuro
        </button>
      </header>

      <section className="usuario" aria-label="Usuario de prueba">
        <label htmlFor="usuario">Usuario de prueba</label>
        <select id="usuario" value={usuarioId} onChange={(e) => cambiarUsuario(e.target.value)}>
          {usuarios.map((u) => (
            <option key={u.id} value={u.id}>
              {u.nombre} ({u.rol}) · {u.programa}
            </option>
          ))}
        </select>
        {errorUsuarios && <p role="alert" className="error">{errorUsuarios}</p>}
      </section>

      <main>
        <h2 className="sr-only">Conversación</h2>
        <ol className="conversacion" aria-live="polite" aria-relevant="additions">
          {mensajes.length === 0 && (
            <li className="vacio">Escribe una pregunta sobre el reglamento o tus datos académicos.</li>
          )}
          {mensajes.map((m) => {
            if (m.tipo === 'pregunta')
              return (
                <li key={m.id} className="msg msg-pregunta">
                  <span className="sr-only">Tu pregunta: </span>
                  {m.texto}
                </li>
              );
            if (m.tipo === 'error')
              return (
                <li
                  key={m.id}
                  className={`msg ${m.clase === 'permisos' ? 'msg-permisos' : 'msg-error'}`}
                  role="alert"
                >
                  <strong>{m.clase === 'permisos' ? 'Sin permiso' : 'Error'}</strong>
                  <p>{m.texto}</p>
                </li>
              );
            return (
              <li key={m.id} className="msg msg-respuesta">
                <span className="sr-only">Respuesta del asistente: </span>
                <p className="texto">{m.texto}</p>
                {m.uso && <p className="badge">Usó tus datos de estudiante</p>}
                {m.citas.length > 0 && (
                  <ul className="citas" aria-label="Citas">
                    {m.citas.map((c) => (
                      <li key={`${c.documento}|${c.seccion}`}>
                        <button
                          type="button"
                          className="cita"
                          onClick={(e) => abrirCita(c, e.currentTarget)}
                        >
                          {c.documento} · {c.seccion}
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
                <p className="meta">
                  {formatoTokens(m.tokens)} tokens · USD {formatoCosto(m.costoUsd)}
                </p>
              </li>
            );
          })}
          {enviando && (
            <li className="msg msg-estado" role="status">
              Consultando…
            </li>
          )}
        </ol>
      </main>

      <form className="formulario" onSubmit={enviar}>
        <label htmlFor="pregunta">Tu pregunta</label>
        <textarea
          id="pregunta"
          value={texto}
          maxLength={MAX}
          rows={3}
          onChange={(e) => setTexto(e.target.value)}
          onKeyDown={onKeyDown}
          aria-describedby="contador ayuda"
        />
        <div className="fila">
          <span id="contador" className="muted">
            {texto.length}/{MAX}
          </span>
          <span id="ayuda" className="muted">
            Enter envía, Shift+Enter agrega una línea
          </span>
          <button type="submit" disabled={vacio || enviando || !usuario}>
            Enviar
          </button>
        </div>
      </form>

      <footer className="totales" aria-label="Acumulado de la sesión">
        Sesión: {formatoTokens(total.tokens)} tokens · USD {formatoCosto(total.costoUsd)}
      </footer>

      {citaAbierta && <CitaDialog cita={citaAbierta} onClose={cerrarCita} />}
    </div>
  );
}

:root {
  --bg: #f6f7f9;
  --surface: #fff;
  --text: #1b1f24;
  --muted: #5a6572;
  --border: #cfd6de;
  --accent: #1d4ed8;
  --accent-text: #fff;
  --perm-bg: #fff4e0;
  --perm-border: #b45309;
  --err-bg: #fdecec;
  --err-border: #b42318;
  --ok-bg: #e3f4ea;
  --ok-text: #14532d;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-tema='light']) {
    --bg: #12151a; --surface: #1c2128; --text: #e6e9ee; --muted: #9aa5b1; --border: #3a4350;
    --accent: #6ea0ff; --accent-text: #0b1220; --perm-bg: #3a2a10; --perm-border: #f0a53c;
    --err-bg: #3b1a1a; --err-border: #f08080; --ok-bg: #153523; --ok-text: #8fe0ae;
    color-scheme: dark;
  }
}
:root[data-tema='dark'] {
  --bg: #12151a; --surface: #1c2128; --text: #e6e9ee; --muted: #9aa5b1; --border: #3a4350;
  --accent: #6ea0ff; --accent-text: #0b1220; --perm-bg: #3a2a10; --perm-border: #f0a53c;
  --err-bg: #3b1a1a; --err-border: #f08080; --ok-bg: #153523; --ok-text: #8fe0ae;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { margin: 0; overflow-x: hidden; }
body { background: var(--bg); color: var(--text); font: 16px/1.5 system-ui, sans-serif; }
.app { max-width: 760px; margin: 0 auto; padding: 12px; display: flex; flex-direction: column; gap: 12px; min-height: 100vh; }
h1 { font-size: 1.4rem; margin: 0; }
h2 { font-size: 1.1rem; margin: 0 0 4px; }
.cabecera { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }
.usuario { display: flex; flex-direction: column; gap: 4px; }
label { font-weight: 600; }
select, textarea, button { font: inherit; color: inherit; }
select, textarea { width: 100%; padding: 8px; background: var(--surface); border: 1px solid var(--border); border-radius: 6px; }
textarea { resize: vertical; }
button { padding: 8px 14px; border-radius: 6px; border: 1px solid var(--accent); background: var(--accent); color: var(--accent-text); cursor: pointer; }
button.secundario { background: transparent; color: var(--text); border-color: var(--border); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.conversacion { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.msg { padding: 10px 12px; border-radius: 8px; border: 1px solid var(--border); background: var(--surface); overflow-wrap: anywhere; }
.msg p { margin: 4px 0; }
.msg-pregunta { align-self: flex-end; max-width: 90%; border-color: var(--accent); }
.msg-respuesta .texto { white-space: pre-wrap; }
.msg-permisos { background: var(--perm-bg); border: 2px solid var(--perm-border); }
.msg-error { background: var(--err-bg); border: 1px dashed var(--err-border); }
.vacio, .msg-estado, .muted, .meta { color: var(--muted); }
.vacio { list-style: none; }
.meta { font-size: 0.85rem; }
.badge { display: inline-block; background: var(--ok-bg); color: var(--ok-text); padding: 2px 8px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; }
.citas { list-style: none; padding: 0; margin: 6px 0; display: flex; flex-wrap: wrap; gap: 6px; }
button.cita { background: transparent; color: var(--accent); border-color: var(--accent); font-size: 0.9rem; text-align: left; overflow-wrap: anywhere; }
.formulario { display: flex; flex-direction: column; gap: 6px; }
.fila { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.fila button { margin-left: auto; }
.totales { font-size: 0.9rem; color: var(--muted); border-top: 1px solid var(--border); padding-top: 8px; }
.error { color: var(--err-border); }
.cita-dialog { width: min(640px, calc(100vw - 24px)); max-height: 85vh; background: var(--surface); color: var(--text); border: 1px solid var(--border); border-radius: 10px; padding: 16px; }
.cita-dialog::backdrop { background: rgba(0, 0, 0, 0.55); }
.cita-texto { white-space: pre-wrap; overflow-wrap: anywhere; font: inherit; margin: 8px 0; max-height: 55vh; overflow-y: auto; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }

import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import App from './App';
import { acumular, errorDeEstado, formatoCosto, urlSeccion } from './api';

const usuarios = [
  { id: 'E-001', rol: 'estudiante', nombre: 'Ana', programa: 'Ingeniería de Sistemas' },
  { id: 'C-001', rol: 'coordinador', nombre: 'Laura', programa: 'Ingeniería de Sistemas' },
];
const json = (body: unknown, status = 200) =>
  Promise.resolve(new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } }));

describe('mapeo de errores', () => {
  it('traduce 400, 403 y 503 a mensajes propios', () => {
    expect(errorDeEstado(400).tipo).toBe('entrada');
    expect(errorDeEstado(403).tipo).toBe('permisos');
    expect(errorDeEstado(403).message).toMatch(/^No tienes permiso para consultar esos datos/);
    expect(errorDeEstado(503).tipo).toBe('proveedor');
    expect(errorDeEstado(500).tipo).toBe('generico');
    const textos = new Set([400, 403, 503, 500].map((s) => errorDeEstado(s).message));
    expect(textos.size).toBe(4);
  });
});

describe('acumulado', () => {
  it('suma tokens y costo y formatea con 6 decimales', () => {
    const t = acumular([
      { tokens: 100, costoUsd: 0.000123 },
      { tokens: 50, costoUsd: 0.000077 },
    ]);
    expect(t.tokens).toBe(150);
    expect(formatoCosto(t.costoUsd)).toBe(formatoCosto(0.0002));
    expect(formatoCosto(0.5)).toBe('0,500000');
  });
});

describe('interfaz', () => {
  const fetchMock = vi.fn();
  beforeEach(() => {
    fetchMock.mockReset();
    vi.stubGlobal('fetch', fetchMock);
  });
  afterEach(() => vi.unstubAllGlobals());

  it('muestra 403 como mensaje de permisos, acumula la sesion y abre la cita', async () => {
    const cita = { documento: 'reglamento-academico.md', seccion: 'Artículo 5. Notas & plazos' };
    let preguntas = 0;
    fetchMock.mockImplementation((url: string) => {
      if (url === '/api/usuarios/demo') return json(usuarios);
      if (url === '/api/asistente/preguntar') {
        preguntas++;
        return preguntas === 1
          ? json({ respuesta: 'Hola', citas: [cita], usoDatosEstudiante: true, tokens: 120, costoUsd: 0.0001 })
          : json({ error: 'x' }, 403);
      }
      return json({ documento: cita.documento, seccion: cita.seccion, texto: '<b>texto</b> de la sección' });
    });
    const user = userEvent.setup();
    render(<App />);
    await screen.findByRole('option', { name: /Ana/ });

    const caja = screen.getByLabelText('Tu pregunta');
    await user.type(caja, 'Primera{Enter}');
    await screen.findByText('Hola');
    expect(screen.getByText('Usó tus datos de estudiante')).toBeTruthy();
    expect(screen.getByText(/Sesión: 120 tokens/)).toBeTruthy();

    await user.type(caja, 'Segunda{Enter}');
    const alerta = await screen.findByText(/No tienes permiso para consultar esos datos/);
    expect(alerta.closest('li')?.className).toContain('msg-permisos');

    await user.click(screen.getByRole('button', { name: /reglamento-academico\.md/ }));
    await waitFor(() => expect(screen.getByText(/de la sección/)).toBeTruthy());
    expect(fetchMock).toHaveBeenCalledWith(urlSeccion(cita));
    expect(urlSeccion(cita)).toBe(
      '/api/reglamento/reglamento-academico.md/Art%C3%ADculo%205.%20Notas%20%26%20plazos',
    );
    // texto plano, sin interpretar HTML
    expect(document.querySelector('.cita-texto b')).toBeNull();
  });

  it('no envia preguntas vacias y cambiar de usuario limpia la conversacion', async () => {
    fetchMock.mockImplementation((url: string) =>
      url === '/api/usuarios/demo'
        ? json(usuarios)
        : json({ respuesta: 'R', citas: [], usoDatosEstudiante: false, tokens: 1, costoUsd: 0 }),
    );
    const user = userEvent.setup();
    render(<App />);
    await screen.findByRole('option', { name: /Laura/ });
    expect((screen.getByRole('button', { name: 'Enviar' }) as HTMLButtonElement).disabled).toBe(true);
    await user.type(screen.getByLabelText('Tu pregunta'), 'hola{Enter}');
    await screen.findByText('R');
    await user.selectOptions(screen.getByLabelText('Usuario de prueba'), 'C-001');
    expect(screen.queryByText('R')).toBeNull();
  });
});
